    "scripts/run-context-dev.test.ts":
      '// Samebase source build: v1997\nimport { execFileSync } from "node:child_process";\nimport { mkdtempSync, rmSync } from "node:fs";\nimport { tmpdir } from "node:os";\nimport path from "node:path";\nimport { describe, expect, it } from "vite-plus/test";\n\nimport { resolveWorktreeKind, selectDevRunner } from "./run-context-dev.ts";\n\ndescribe("run-context-dev", () => {\n  it("selects the primary runner for the main Git worktree", () => {\n    expect(selectDevRunner("main")).toBe("run-primary-dev.ts");\n  });\n\n  it("selects the worktree runner for a linked Git worktree", () => {\n    expect(selectDevRunner("linked")).toBe("run-worktree-dev.ts");\n  });\n\n  it("detects main and linked Git worktrees", () => {\n    const temporaryDirectory = mkdtempSync(path.join(tmpdir(), "samebase-base-run-dev-test-"));\n    const mainWorktree = path.join(temporaryDirectory, "main");\n    const linkedWorktree = path.join(temporaryDirectory, "linked");\n\n    try {\n      execFileSync("git", ["init", "--initial-branch=main", mainWorktree], { stdio: "pipe" });\n      execFileSync(\n        "git",\n        [\n          "-C",\n          mainWorktree,\n          "-c",\n          "user.name=Samebase test",\n          "-c",\n          "user.email=test@samebase.com",\n          "commit",\n          "--allow-empty",\n          "-m",\n          "Initial commit",\n        ],\n        { stdio: "pipe" },\n      );\n      execFileSync("git", ["-C", mainWorktree, "worktree", "add", "--detach", linkedWorktree], {\n        stdio: "pipe",\n      });\n\n      expect(resolveWorktreeKind(mainWorktree)).toBe("main");\n      expect(resolveWorktreeKind(linkedWorktree)).toBe("linked");\n    } finally {\n      rmSync(temporaryDirectory, { force: true, recursive: true });\n    }\n  });\n});\n',
    "scripts/run-context-dev.ts":
      '// Samebase starter dev launcher sha256:9a19ac6550a3a4deb0617663c683f9ef45e76462f5069f1a24e43faccba4f71c\n// Samebase source build: v1989\n/// <reference types="node" />\nimport { spawn, spawnSync } from "node:child_process";\nimport process from "node:process";\nimport { fileURLToPath } from "node:url";\n\nexport type WorktreeKind = "main" | "linked";\n\nexport function selectDevRunner(kind: WorktreeKind) {\n  return kind === "main" ? "run-primary-dev.ts" : "run-worktree-dev.ts";\n}\n\nexport function resolveWorktreeKind(cwd = process.cwd()): WorktreeKind {\n  const result = spawnSync(\n    "git",\n    ["rev-parse", "--path-format=absolute", "--git-dir", "--git-common-dir"],\n    {\n      cwd,\n      encoding: "utf8",\n    },\n  );\n  if (result.error) {\n    throw result.error;\n  }\n  if (result.status !== 0) {\n    throw new Error("Run the development command from inside a Git checkout.");\n  }\n\n  const [gitDir, gitCommonDir] = result.stdout.trim().split(/\\r?\\n/);\n  if (!gitDir || !gitCommonDir) {\n    throw new Error("Git did not return enough metadata to select a development mode.");\n  }\n\n  return gitDir === gitCommonDir ? "main" : "linked";\n}\n\nasync function main() {\n  const runnerPath = fileURLToPath(\n    new URL(selectDevRunner(resolveWorktreeKind()), import.meta.url),\n  );\n\n  await new Promise<void>((resolve, reject) => {\n    const child = spawn(process.execPath, [runnerPath, ...process.argv.slice(2)], {\n      stdio: "inherit",\n    });\n\n    child.once("error", reject);\n    child.once("exit", (code, signal) => {\n      if (signal) {\n        process.kill(process.pid, signal);\n        return;\n      }\n      if (code === 0) {\n        resolve();\n        return;\n      }\n      reject(new Error(`Development startup failed with exit code ${code ?? 1}.`));\n    });\n  });\n}\n\nif (process.argv[1] === fileURLToPath(import.meta.url)) {\n  try {\n    await main();\n  } catch (error) {\n    console.error(error instanceof Error ? error.message : String(error));\n    process.exit(1);\n  }\n}\n',
